def findShortestPath(matrix):
    from collections import deque

    R, C = len(matrix), len(matrix[0])

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Function to check if a cell is within bounds and safe
    def is_safe(x, y):
        return 0 <= x < R and 0 <= y < C and matrix[x][y] == 1

    # BFS to find the shortest path
    def bfs():
        queue = deque()

        # Initialize the queue with all safe starting points in the first column
        for r in range(R):
            if matrix[r][0] == 1:
                queue.append((r, 0, 1))  # (row, col, distance)

        while queue:
            x, y, dist = queue.popleft()

            # If we reach the last column, return the distance
            if y == C - 1:
                return dist

            # Explore all four possible directions
            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                # Check if the new position is safe and not visited
                if is_safe(nx, ny):
                    matrix[nx][ny] = 0  # Mark as visited by setting to 0
                    queue.append((nx, ny, dist + 1))

        # If no path is found, return -1
        return -1

    return bfs()
